attempts.rawText:
{
  "layer1": "⑤가 ㉠을 주체와 대상이 미리 나뉘어 있다고 보는 주장으로 읽은 데까지는 맞아. 그런데 (나)의 필자는 그런 주장을 받아들이지 않아.",
  "symbolGlosses": [
    {
      "symbol": "㉠",
      "gloss": "인지 과정은 주체와 통합되어야 성립한다는 주장"
    },
    {
      "symbol": "(나)",
      "gloss": "지각 이후 주체와 대상이 확정된다고 보는 글"
    }
  ],
  "pair": {
    "top": "주체와 통합된 경우에만 확장된 인지 과정이 성립할 수 있다는 주장",
    "source": "다시 말해 주체와 대상은 지각이 일어난 이후 비로소 확정된다.",
    "sourceFocus": "지각이 일어난 이후 비로소 확정된다",
    "conclusion": "주체가 먼저 정해져 있어야 한다는 주장은 글쓴이가 받아들일 수 없으므로, ⑤의 ‘타당하다’는 맞지 않아."
  },
  "examinerIntent": "출제자는 ㉠이 미리 정해진 주체를 전제한다는 점을 짚으면서도, 그것을 글쓴이가 타당하다고 여기는 것처럼 선지를 만들었어. 주체와 대상이 먼저 나뉘어 있어야 지각한다는 생각은 글쓴이가 받아들이는 생각이 아니라 비판하는 생각이야.",
  "selfCheckOptions": [
    "㉠의 내용을 맞게 설명했으니 ‘타당하다’는 평가도 맞다고 봤어.",
    "글쓴이도 주체와 대상이 먼저 나뉘어 있어야 지각한다고 봤어.",
    "㉠의 주장과 글쓴이의 생각을 어떻게 연결할지 잘 몰랐어."
  ]
}
